 for(unsigned port=0;port<2;++port){for(unsigned input=0;input<256;++input)run(Job(Job::Curve{27},port?ks::NativeDspJob::Port::B:ks::NativeDspJob::Port::A),0x844e,0x847a,27,0,input,port,input&7);run(Job(Job::Curve{27},port?ks::NativeDspJob::Port::B:ks::NativeDspJob::Port::A),0x844e,0x847a,27,0,93,port,65537);for(unsigned pause=0;pause<32;++pause)run(Job(Job::Curve{27},port?ks::NativeDspJob::Port::B:ks::NativeDspJob::Port::A),0x844e,0x847a,27,0,93,port,3,~0u,pause);}
