 for(unsigned port=0;port<2;++port){for(unsigned input=0;input<256;++input)run(Job(Job::SignedSquare{57},port?ks::NativeDspJob::Port::B:ks::NativeDspJob::Port::A),0x88ea,0x890e,57,0,input,port,input&7);run(Job(Job::SignedSquare{57},port?ks::NativeDspJob::Port::B:ks::NativeDspJob::Port::A),0x88ea,0x890e,57,0,93,port,65537);for(unsigned pause=0;pause<32;++pause)run(Job(Job::SignedSquare{57},port?ks::NativeDspJob::Port::B:ks::NativeDspJob::Port::A),0x88ea,0x890e,57,0,93,port,3,~0u,pause);}
 for(unsigned port=0;port<2;++port){for(unsigned input=0;input<256;++input)run(Job(Job::SignedSquare{172},port?ks::NativeDspJob::Port::B:ks::NativeDspJob::Port::A),0x890e,0x8932,172,0,input,port,input&7);run(Job(Job::SignedSquare{172},port?ks::NativeDspJob::Port::B:ks::NativeDspJob::Port::A),0x890e,0x8932,172,0,93,port,65537);for(unsigned pause=0;pause<32;++pause)run(Job(Job::SignedSquare{172},port?ks::NativeDspJob::Port::B:ks::NativeDspJob::Port::A),0x890e,0x8932,172,0,93,port,3,~0u,pause);}

