  for(unsigned pair=0;pair<65536;++pair){run(Job(Job::Header{ks::ParameterHeaderTask::Kind::Header},p),0x7de4,0x7e20,6,0,pair&255,port,pair&7,pair);run(Job(Job::Header{ks::ParameterHeaderTask::Kind::Part},p),0x8ae8,0x8b00,6,0,pair&255,port,pair&7,pair);}
