 bus.fieldAddress=bus.baseAddress=0xffffffffu;
 for(unsigned raw=0;raw<65536;++raw){ks::NativeCoefficientJob job{int16_t(raw)};for(unsigned i=0;i<8;++i)h->regs[i].er=int32_t(rng());h->setSP(0xa18000);h->pushPC(h->makepc(0x4338));h->pc=h->makepc(0xa69e);h->regs[0].r=int16_t(raw);h->ccr=uint8_t(raw);h->exr=0;h->cycles=1000;h->pending_irqs=h->pending_irqs_high=0;uint64_t now=1000;while(!job.complete()){const auto cost=job.nextClocks();check(!job.advanceBefore(cost-1).clocks,"early coefficient");auto progress=job.advanceBefore(cost);h->step();now+=progress.clocks;check(h->cycles==now,"coefficient time");++boundaries;}check(h->getPC()==0x4338&&h->regs[0].er==job.value(),"typed coefficient result");++cases;}
